                try writer.write((self.bounds.max.x == 0 ? 0.0 : self.bounds.max.x).bitPattern, width: 64)
                if self.bounds.max.y.isNaN { throw GesWireError(code: GesWireError.notRepresentable, path: paths[at + 15]) }
                try writer.write((self.bounds.max.y == 0 ? 0.0 : self.bounds.max.y).bitPattern, width: 64)
                if self.bounds.max.z.isNaN { throw GesWireError(code: GesWireError.notRepresentable, path: paths[at + 16]) }
                try writer.write((self.bounds.max.z == 0 ? 0.0 : self.bounds.max.z).bitPattern, width: 64)
            } else {
                try writer.write(0, width: 1)
            }
            if self.outline.count > 3 { throw GesWireError(code: GesWireError.tooLong, path: paths[at + 17]) }
            try writer.write(UInt64(self.outline.count), width: 2)
            for item in self.outline {
                try writer.write(
                    try GesWireRules.quantizedIndex(item.x, lowerValue: Double(bitPattern: 0x0000000000000000), upperValue: Double(bitPattern: 0x4059000000000000), tenPower: 1.0, numerator: 1.0, lower: 0, path: paths[at + 19]),
                    width: 7
                )
                try writer.write(
                    try GesWireRules.quantizedIndex(item.y, lowerValue: Double(bitPattern: 0x0000000000000000), upperValue: Double(bitPattern: 0x4008000000000000), tenPower: 1.0, numerator: 1.0, lower: 0, path: paths[at + 20]),
                    width: 2
                )
