                try writer.write((item.x == 0 ? 0.0 : item.x).bitPattern, width: 64)
                if item.y.isNaN { throw GesWireError(code: GesWireError.notRepresentable, path: paths[at + 24]) }
                try writer.write((item.y == 0 ? 0.0 : item.y).bitPattern, width: 64)
