            }
            switch self.pick {
            case .box:
                try writer.write(0, width: 1)
                if self.pickBox.min.x.isNaN { throw GesWireError(code: GesWireError.notRepresentable, path: paths[at + 28]) }
                try writer.write((self.pickBox.min.x == 0 ? 0.0 : self.pickBox.min.x).bitPattern, width: 64)
                if self.pickBox.min.y.isNaN { throw GesWireError(code: GesWireError.notRepresentable, path: paths[at + 29]) }
