                try writer.write((self.pickBox.max.y == 0 ? 0.0 : self.pickBox.max.y).bitPattern, width: 64)
                if self.pickBox.max.z.isNaN { throw GesWireError(code: GesWireError.notRepresentable, path: paths[at + 34]) }
                try writer.write((self.pickBox.max.z == 0 ? 0.0 : self.pickBox.max.z).bitPattern, width: 64)

            case .nothing:
                try writer.write(1, width: 1)

            }
            if self.rings.count > 2 { throw GesWireError(code: GesWireError.tooLong, path: paths[at + 36]) }
            try writer.write(UInt64(self.rings.count), width: 2)
            for item in self.rings {
                try item.__writeFields(&writer, paths, at + 37)
            }
        }

        func __readFields(_ reader: inout GesBitReader, _ paths: [String], _ at: Int) throws(GesWireError) {
            do {
                let index = try reader.read(8, path: paths[at + 0])
                self.id = Int64(bitPattern: 0 &+ index)
            }
            do {
                var lower1 = GesPoint()
                do {
                    let index = try reader.read(7, path: paths[at + 3])
                    if index > 100 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 3]) }
                    lower1.x = GesWireRules.quantizedValue(index, lower: 0, numerator: 1, tenPower: 1.0)
                }
                do {
                    let index = try reader.read(2, path: paths[at + 4])
                    lower1.y = GesWireRules.quantizedValue(index, lower: 0, numerator: 1, tenPower: 1.0)
                }
                lower1.z = 0
                var upper1 = GesPoint()
                do {
                    let index = try reader.read(7, path: paths[at + 6])
                    if index > 100 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 6]) }
                    upper1.x = GesWireRules.quantizedValue(index, lower: 0, numerator: 1, tenPower: 1.0)
                }
                do {
                    let index = try reader.read(2, path: paths[at + 7])
                    upper1.y = GesWireRules.quantizedValue(index, lower: 0, numerator: 1, tenPower: 1.0)
                }
                upper1.z = 0
                self.area = GesBox(lower1, upper1)
            }
            self.hasBounds = try reader.read(1, path: paths[at + 8]) != 0
            if self.hasBounds {
                do {
                    var lower8 = GesPoint()
                    do {
                        let bits = try reader.read(64, path: paths[at + 10])
                        let value = Double(bitPattern: bits)
                        if value.isNaN || bits == 0x8000_0000_0000_0000 { throw GesWireError(code: GesWireError.invalidNumber, path: paths[at + 10]) }
                        lower8.x = value
                    }
                    do {
                        let bits = try reader.read(64, path: paths[at + 11])
                        let value = Double(bitPattern: bits)
                        if value.isNaN || bits == 0x8000_0000_0000_0000 { throw GesWireError(code: GesWireError.invalidNumber, path: paths[at + 11]) }
                        lower8.y = value
                    }
                    do {
                        let bits = try reader.read(64, path: paths[at + 12])
                        let value = Double(bitPattern: bits)
                        if value.isNaN || bits == 0x8000_0000_0000_0000 { throw GesWireError(code: GesWireError.invalidNumber, path: paths[at + 12]) }
                        lower8.z = value
                    }
                    var upper8 = GesPoint()
                    do {
                        let bits = try reader.read(64, path: paths[at + 14])
                        let value = Double(bitPattern: bits)
                        if value.isNaN || bits == 0x8000_0000_0000_0000 { throw GesWireError(code: GesWireError.invalidNumber, path: paths[at + 14]) }
                        upper8.x = value
                    }
                    do {
                        let bits = try reader.read(64, path: paths[at + 15])
                        let value = Double(bitPattern: bits)
                        if value.isNaN || bits == 0x8000_0000_0000_0000 { throw GesWireError(code: GesWireError.invalidNumber, path: paths[at + 15]) }
                        upper8.y = value
                    }
                    do {
                        let bits = try reader.read(64, path: paths[at + 16])
                        let value = Double(bitPattern: bits)
                        if value.isNaN || bits == 0x8000_0000_0000_0000 { throw GesWireError(code: GesWireError.invalidNumber, path: paths[at + 16]) }
                        upper8.z = value
                    }
                    self.bounds = GesBox(lower8, upper8)
                }
            } else {
                self.bounds = GesBox(GesPoint(), GesPoint())
            }
            do {
                let count = Int(try reader.read(2, path: paths[at + 17]))
                if count > 3 { throw GesWireError(code: GesWireError.invalidCount, path: paths[at + 17]) }
                self.outline.removeAll(keepingCapacity: true)
                for _ in 0..<count {
                    var item = GesPoint()
                    do {
                        let index = try reader.read(7, path: paths[at + 19])
                        if index > 100 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 19]) }
                        item.x = GesWireRules.quantizedValue(index, lower: 0, numerator: 1, tenPower: 1.0)
                    }
                    do {
                        let index = try reader.read(2, path: paths[at + 20])
                        item.y = GesWireRules.quantizedValue(index, lower: 0, numerator: 1, tenPower: 1.0)
                    }
                    item.z = 0
                    self.outline.append(item)
                }
            }
            do {
                let count = Int(try reader.read(3, path: paths[at + 21]))
                if count > 4 { throw GesWireError(code: GesWireError.invalidCount, path: paths[at + 21]) }
                self.free.removeAll(keepingCapacity: true)
                for _ in 0..<count {
                    var item = GesPoint()
                    do {
                        let bits = try reader.read(64, path: paths[at + 23])
                        let value = Double(bitPattern: bits)
                        if value.isNaN || bits == 0x8000_0000_0000_0000 { throw GesWireError(code: GesWireError.invalidNumber, path: paths[at + 23]) }
