                    self.free.append(item)
                }
            }
            do {
                let choice = try reader.read(1, path: paths[at + 25])
                self.pick = PickAlternative(rawValue: UInt8(choice))!
                switch choice {
                case 0:
                    do {
                        var lower26 = GesPoint()
                        do {
                            let bits = try reader.read(64, path: paths[at + 28])
                            let value = Double(bitPattern: bits)
                            if value.isNaN || bits == 0x8000_0000_0000_0000 { throw GesWireError(code: GesWireError.invalidNumber, path: paths[at + 28]) }
