        private func __same17(_ baseline: Zone, _ paths: [String], _ at: Int) throws(GesWireError) -> Bool {
            if self.outline.count != baseline.outline.count { return false }
            for index17 in 0..<self.outline.count {
                if try Self.__wire19(self.outline[index17].x, paths, at) != Self.__wire19(baseline.outline[index17].x, paths, at) { return false }
                if try Self.__wire20(self.outline[index17].y, paths, at) != Self.__wire20(baseline.outline[index17].y, paths, at) { return false }
            }
            return true
        }

