            for index21 in 0..<self.free.count {
                if try Self.__wire23(self.free[index21].x, paths, at) != Self.__wire23(baseline.free[index21].x, paths, at) { return false }
                if try Self.__wire24(self.free[index21].y, paths, at) != Self.__wire24(baseline.free[index21].y, paths, at) { return false }
